SELECT amount_bucket, status, amount_range FROM (SELECT CASE WHEN amount >= 1620 THEN 'high' WHEN amount >= 360 THEN 'mid' ELSE 'low' END AS amount_bucket, status, MAX(amount) - MIN(amount) AS amount_range FROM orders WHERE channel IN ('partner', 'mobile', 'store') GROUP BY CASE WHEN amount >= 1620 THEN 'high' WHEN amount >= 360 THEN 'mid' ELSE 'low' END, status) AS x WHERE amount_range > 74 ORDER BY status
